const cases = [
{title:'O computador não liga',level:'Iniciante',area:'Alimentação',symptom:'“Ontem funcionava normalmente. Hoje aperto o botão e nada acontece. Não acende nenhuma luz e não ouço as ventoinhas.”',screen:'SEM SINAL',on:false,tests:[['Verificar tomada e cabo','A tomada funciona com outro equipamento. O cabo de alimentação está firme e passou no teste de continuidade.','any'],['Inspecionar conexões internas','Com a energia desconectada, os conectores ATX e CPU estão corretamente encaixados. Não há sinais visíveis de curto.','off'],['Testar com fonte compatível','Na simulação, uma fonte compatível e comprovadamente funcional faz o PC iniciar normalmente.','off']],options:['Fonte de alimentação com defeito','Monitor sem alimentação','Sistema operacional corrompido','Memória RAM insuficiente'],answer:0,repair:'Substituir a fonte por uma unidade compatível',hardware:true,why:'O teste por substituição isolou a fonte como causa. A tomada, o cabo e os conectores já haviam sido verificados. Um monitor com defeito não explica, sozinho, a ausência de energia no gabinete.',hint:'Antes de suspeitar do sistema, confirme o caminho da energia. Um teste com uma fonte funcional pode isolar a causa.'},
{title:'Liga, mas não aparece imagem',level:'Iniciante',area:'Memória',symptom:'“As ventoinhas giram, mas a tela fica preta. Isso começou depois que transportei o gabinete para outra sala.”',screen:'SEM SINAL',on:true,tests:[['Testar monitor e cabo','O monitor e o cabo exibem imagem em outro computador. A entrada selecionada está correta.','any'],['Observar indicadores de POST','A placa desta bancada mantém o LED DRAM aceso. O manual desse modelo aponta falha na inicialização da memória.','on'],['Inspecionar módulos de RAM','Um módulo está parcialmente fora do slot e sua trava lateral está aberta.','off']],options:['Cabo de vídeo defeituoso','Memória RAM mal encaixada','Driver de áudio ausente','SSD cheio'],answer:1,repair:'Reencaixar a memória e fechar as travas',hardware:true,why:'O LED DRAM orientou a investigação e a inspeção confirmou o encaixe incompleto. Indicadores e códigos variam entre placas: consulte sempre o manual do modelo.',hint:'O transporte pode soltar um componente. Investigue o indicador de inicialização antes de trocar peças.'},
{title:'Desliga durante os jogos',level:'Intermediário',area:'Refrigeração',symptom:'“Posso navegar por horas. Mas, quando abro um jogo, o computador fica lento e logo desliga sozinho.”',screen:'CPU 98 °C\nTHERMAL LIMIT',on:true,tests:[['Monitorar temperaturas','Sob carga, a CPU chega a 98 °C, reduz o clock e desliga. A GPU permanece a 65 °C.','on'],['Inspecionar o cooler','O dissipador da CPU está obstruído por poeira; o fluxo de ar está muito reduzido.','off'],['Verificar logs do sistema','Há registro de proteção térmica imediatamente antes do desligamento. Não há erro de armazenamento.','on']],options:['Falha de DNS','Monitor superaquecido','Superaquecimento da CPU','Memória insuficiente'],answer:2,repair:'Limpar o dissipador e restabelecer o fluxo de ar',hardware:true,why:'A temperatura, o registro térmico e a obstrução do dissipador convergem para superaquecimento. Após o reparo simulado, a CPU se estabiliza em 71 °C sob a mesma carga.',hint:'Compare a temperatura em repouso e sob carga. Um desligamento não significa automaticamente defeito na fonte.'},
{title:'Nenhum sistema encontrado',level:'Intermediário',area:'Armazenamento',symptom:'“Ao ligar, aparece uma mensagem de que não existe dispositivo de inicialização. O computador foi limpo recentemente.”',screen:'BOOT DEVICE\nNOT FOUND',on:true,tests:[['Consultar unidades na UEFI','O SSD SATA do sistema não aparece na lista de dispositivos detectados.','on'],['Inspecionar cabos do SSD','O cabo de dados SATA está solto no lado do SSD. A alimentação está conectada.','off'],['Testar o SSD em bancada','O SSD é reconhecido com outro cabo e passa no teste de saúde da bancada.','off']],options:['Cabo SATA desconectado','Sistema precisa ser formatado','Falha na tela','Driver de rede incorreto'],answer:0,repair:'Reconectar corretamente o cabo de dados SATA',hardware:true,why:'A unidade estava saudável e faltava a conexão de dados. Reconectar o cabo restabelece a detecção e a inicialização. Formatar não resolveria uma conexão física e poderia destruir dados.',hint:'Se a UEFI não detecta a unidade, examine primeiro as conexões e a própria unidade.'},
{title:'Conectado, mas sem navegar',level:'Intermediário',area:'Rede',symptom:'“O ícone diz que estou conectado. Mesmo assim, os sites não abrem. Os outros computadores acessam normalmente.”',screen:'DNS_PROBE\nFINISHED_BAD_CONFIG',on:true,tests:[['Verificar conexão local','O computador tem IP válido e consegue alcançar o gateway da rede.','on'],['Testar acesso por IP','Um destino externo de teste responde por IP. Há conectividade além da rede local.','on'],['Testar resolução de nomes','As consultas ao DNS configurado expiram. Um servidor DNS autorizado da rede resolve os mesmos nomes.','on']],options:['Cabo de rede rompido','Falha na resolução DNS','Fonte defeituosa','Monitor desconectado'],answer:1,repair:'Corrigir o DNS para o servidor autorizado da rede',hardware:false,why:'A conectividade local e externa funciona por IP, mas a tradução de nomes falha. Corrigir a configuração de DNS restaura as consultas no teste simulado.',hint:'Compare acesso por endereço IP e por nome. A diferença ajuda a localizar o problema.'},
{title:'O áudio desapareceu',level:'Iniciante',area:'Drivers',symptom:'“Depois de reinstalar o sistema, o computador ficou sem som. As caixas de som funcionam no meu celular.”',screen:'NENHUM DISPOSITIVO\nDE ÁUDIO ENCONTRADO',on:true,tests:[['Verificar saída e volume','As caixas estão alimentadas e conectadas à saída correta. O volume não está silenciado.','any'],['Inspecionar dispositivos','O controlador de áudio aparece sem driver no gerenciador de dispositivos.','on'],['Verificar identificação do hardware','O identificador corresponde ao controlador de áudio integrado. O pacote oficial compatível está disponível na bancada.','on']],options:['Caixas queimadas','Memória RAM defeituosa','Driver de áudio ausente','SSD desconectado'],answer:2,repair:'Instalar o driver oficial compatível com o controlador',hardware:false,why:'O controlador sem driver não é disponibilizado corretamente ao sistema. Após instalar o pacote compatível, a saída aparece e reproduz o som de teste.',hint:'Uma reinstalação pode deixar dispositivos sem seus drivers. Verifique o controlador antes de trocar as caixas.'},
{title:'Lentidão logo ao iniciar',level:'Intermediário',area:'Sistema',symptom:'“O PC demora muito para ficar utilizável. Depois de alguns minutos ele melhora, mas isso acontece todos os dias.”',screen:'INICIALIZANDO…\nCPU 94% · DISCO 100%',on:true,tests:[['Analisar processos na inicialização','Vários aplicativos opcionais iniciam juntos, consumindo CPU e disco nos primeiros minutos.','on'],['Verificar saúde e espaço do SSD','A unidade passa nos testes de saúde e possui 45% de espaço livre.','on'],['Testar inicialização seletiva','Com aplicativos opcionais desativados na inicialização, o tempo até ficar utilizável cai de 4 minutos para 35 segundos.','on']],options:['Excesso de aplicativos na inicialização','Falha no cabo de vídeo','Fonte sem energia','Cooler desconectado'],answer:0,repair:'Desativar aplicativos opcionais na inicialização',hardware:false,why:'A comparação controlada confirmou o impacto dos aplicativos. Desative apenas itens reconhecidos e opcionais; mantenha segurança, drivers e serviços essenciais.',hint:'Observe quando a lentidão acontece e compare o comportamento com uma inicialização seletiva.'},
{title:'Artefatos na tela',level:'Avançado',area:'Vídeo',symptom:'“Aparecem blocos coloridos e linhas estranhas, inclusive antes de entrar no sistema operacional.”',screen:'▥ ▧ ▨ ▥\n▦ ▥ ▧ ▨',on:true,tests:[['Trocar monitor e cabo','Os mesmos artefatos aparecem com outro monitor e outro cabo funcionais.','any'],['Observar a tela da UEFI','Os artefatos também estão presentes na UEFI, antes do carregamento de drivers do sistema.','on'],['Testar outra placa de vídeo','Uma placa compatível e funcional elimina os artefatos na mesma configuração.','off']],options:['Configuração de DNS','Driver de áudio','Somente cabo do monitor','Falha na placa de vídeo'],answer:3,repair:'Substituir a placa de vídeo por uma compatível',hardware:true,why:'A falha aparece antes do sistema e persiste com outro monitor e cabo. A substituição controlada da GPU elimina o sintoma e confirma o diagnóstico deste caso.',hint:'Verifique se o defeito aparece antes do sistema operacional e compare com outra saída de vídeo funcional.'},
...extraCases
];
const KEY='bancada-pc-v1';let saved={best:{},current:0,runs:{}};let storageOK=true;
try{saved=readProgress(localStorage.getItem(KEY),cases)}catch{storageOK=false}
let current=saved.current,view='lab',runs=saved.runs;const app=document.querySelector('#app'),modal=document.querySelector('#modal');
function state(){return runs[current]??= {power:cases[current].on,tests:[],penalty:0,hint:false,diagnosed:false,solved:false,wrong:[]}}
function persist(){saved.runs=runs;try{localStorage.setItem(KEY,JSON.stringify(saved));storageOK=true}catch{storageOK=false}document.querySelector('.save-status').innerHTML=storageOK?'<i></i> Progresso salvo neste navegador':'Progresso apenas nesta sessão'}
function stats(){let count=Object.keys(saved.best).length,total=Object.values(saved.best).reduce((a,b)=>a+b,0);return `<div class="stats"><div class="stat"><div class="stat-icon">◎</div><div><small>Desafios resolvidos</small><strong>${count.toString().padStart(2,'0')} <span>/ ${cases.length}</span></strong></div></div><div class="stat"><div class="stat-icon">✧</div><div><small>Pontuação total</small><strong>${total.toLocaleString('pt-BR')} <span>pontos</span></strong></div></div><div class="stat"><div class="stat-icon">↗</div><div><small>Seu nível atual</small><strong style="font-size:18px">${count>=6?'Especialista':count>=3?'Investigador':'Aprendiz'}</strong></div></div></div>`}
function title(name,sub,action=''){return `<div class="page-title"><div><div class="eyebrow">APRENDA NA PRÁTICA</div><h1>${name}</h1><p class="subtitle">${sub}</p></div>${action}</div>`}
function render(){document.querySelector('[data-view="missions"] b').textContent=cases.length;state();persist();document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===view));document.querySelector('#crumb').textContent={lab:'Bancada de trabalho',missions:'Todos os desafios',progress:'Meu progresso',guide:'Guia do técnico'}[view];if(view==='lab')renderLab();if(view==='missions')renderMissions();if(view==='progress')renderProgress();if(view==='guide')renderGuide()}
function renderLab(){
 const c=cases[current],s=state();
 app.innerHTML=`<div class="challenge-page">
 <div class="challenge-heading"><div><div class="challenge-meta"><span class="case-num">DESAFIO ${String(current+1).padStart(2,'0')} / ${cases.length}</span><span class="tag">${c.level} · ${c.area}</span></div><h1>${c.title}</h1></div><button class="outline" data-action="missions">Todos os desafios →</button></div>
 <section class="case-report"><span class="section-label">O que está acontecendo?</span><p>${c.symptom}</p></section>
 <div class="challenge-layout"><div class="machine-column"><section class="card machine-card"><div class="panel-heading"><h2>Seu computador</h2><button class="text-button" data-action="help">Como jogar</button></div>${computerView(c,s)}<div class="power-row"><span><i class="status-dot" style="background:${s.power?'#27765d':'#a66a21'}"></i>${s.power?'Computador ligado':'Energia desconectada'}</span><button class="outline" data-action="power" ${s.solved?'disabled':''}>${s.power?'Desligar e desconectar':'Conectar e ligar'}</button></div><p class="energy-help">Desconecte a energia antes de manipular componentes internos.</p></section>${attemptPanel(s)}</div>
 <section class="card investigation"><div class="panel-heading"><div><span class="section-label">Sua investigação</span><h2>Testes e pistas</h2></div><span class="clue-count">${s.tests.length} / 3 pistas</span></div><p class="investigation-intro">Faça pelo menos 2 testes e compare os resultados. Todos os testes são gratuitos.</p><div class="test-list">${c.tests.map((t,i)=>{
 const read=s.tests.includes(i),ready=t[2]==='any'||(t[2]==='on')===s.power;
 return `<article class="test-item ${read?'collected':''}"><button class="test-btn ${read?'used':''}" data-test="${i}" ${s.solved?'disabled':''}><span class="test-number">${read?'✓':i+1}</span><span><strong>${t[0]}</strong><small>${read?'Pista coletada · Clique para rever':ready?'Pronto para testar':t[2]==='off'?'Desconecte a energia para este teste':'Ligue o computador para este teste'}</small></span><b>${read?'Rever':ready?'Testar →':'Preparar'}</b></button>${read?`<p class="inline-clue">${t[1]}</p>`:''}</article>`}).join('')}</div>
 <div class="next-action"><span class="section-label">${s.solved?'Desafio concluído':'Próximo passo'}</span><p>${s.solved?'Reparo validado. Confira o resultado ou escolha outro desafio.':s.diagnosed?`Diagnóstico confirmado. ${c.hardware?'Desconecte a energia':'Ligue o computador'} e aplique o reparo.`:s.tests.length>=2?'Você já tem pistas suficientes. Qual hipótese explica o problema?':`Colete mais ${2-s.tests.length} ${s.tests.length===1?'pista':'pistas'} para liberar o diagnóstico.`}</p><button class="primary diagnosis" data-action="diagnose" ${!s.solved&&!s.diagnosed&&s.tests.length<2?'disabled':''}>${s.solved?'Ver resultado →':s.diagnosed?'Aplicar reparo →':'Escolher diagnóstico →'}</button><button class="text-button hint-link" data-action="hint" ${s.solved?'disabled':''}>${s.hint?'Rever dica':'Preciso de uma dica · −100 pontos'}</button></div></section></div></div>`;
}
function openModal(html){document.querySelector('#modal-content').innerHTML=html;const heading=modal.querySelector('h2');if(heading){heading.id='modal-title';heading.tabIndex=-1;modal.setAttribute('aria-labelledby','modal-title')}if(!modal.open)modal.showModal();heading?.focus()}
function message(title,text){openModal(`<span class="tag">Bancada PC</span><h2>${title}</h2><p>${text}</p><button class="primary" data-action="close">Continuar investigação</button>`)}
function test(i){const s=state(),t=cases[current].tests[i];if(s.solved)return;if(!s.tests.includes(i)&&((t[2]==='off'&&s.power)||(t[2]==='on'&&!s.power))){message('Prepare o computador',t[2]==='off'?'Desligue e desconecte a energia pelo botão da bancada antes deste teste de hardware.':'Conecte e ligue o computador na bancada para executar este teste.');return}if(!s.tests.includes(i))s.tests.push(i);render();message(t[0],t[1])}
function diagnose(){let s=state(),c=cases[current];if(s.solved)return result();if(s.diagnosed)return repair();if(s.tests.length<2)return message('Ainda faltam evidências','Colete pelo menos duas pistas antes de concluir o diagnóstico. Os testes são gratuitos e ajudam a evitar trocas desnecessárias.');openModal(`<span class="tag">Etapa 02 · Diagnóstico</span><h2>Qual é a causa do problema?</h2><p>Relacione as evidências ao relato do cliente.</p><details class="diagnostic-notes"><summary>Consultar pistas coletadas (${s.tests.length})</summary>${s.tests.map(i=>`<p><b>${c.tests[i][0]}</b><br>${c.tests[i][1]}</p>`).join('')}</details><form id="diagnostic-form">${c.options.map((o,i)=>`<label class="option"><input type="radio" name="answer" value="${i}" required ${s.wrong.includes(i)?'disabled':''}>${o}${s.wrong.includes(i)?' · descartado':''}</label>`).join('')}<div id="answer-feedback" aria-live="polite"></div><button class="primary diagnosis" type="submit">Confirmar diagnóstico</button></form>`)}
function repair(){const s=state(),c=cases[current];openModal(`<span class="tag">Diagnóstico correto</span><h2>Agora, resolva o problema.</h2><p>${c.options[c.answer]}.</p><div class="feedback success"><b>Reparo recomendado</b><br>${c.repair}.</div><p>${c.hardware?'Para esse reparo de hardware, desligue e desconecte o computador na bancada. Não abra a fonte de alimentação.':'Esse reparo de software precisa do computador ligado.'}</p><div class="modal-actions"><button class="outline" data-action="close">Voltar à bancada</button><button class="primary" data-action="repair">Aplicar reparo</button></div><div id="repair-feedback" aria-live="polite"></div>`)}
function result(){const s=state(),c=cases[current],score=Math.max(0,1000-s.penalty);openModal(`<span class="tag">✓ Caso resolvido</span><h2>Diagnóstico que faz a diferença.</h2><div class="result-score">+${score} <span style="font-size:16px">pontos</span></div><p>${c.why}</p><div class="feedback success"><b>Validação do reparo</b><br>O computador foi religado e o sintoma não voltou no teste simulado.</div><p>${s.penalty?`Descontos desta tentativa: ${s.penalty} pontos. `:'Investigação concluída sem descontos. '}A melhor pontuação de cada caso conta para o total.</p><div class="modal-actions"><button class="outline" data-action="missions">Ver desafios</button><button class="primary" data-action="next">${Object.keys(saved.best).length===cases.length?'Ver meu progresso':'Próximo desafio →'}</button></div>`)}
function renderMissions(){catalog()}
function renderProgress(){let count=Object.keys(saved.best).length;app.innerHTML=title('Seu conhecimento, em evolução.','Cada caso resolvido é mais uma habilidade para levar à bancada real.')+stats()+`<section class="card guide"><span class="tag">Sua jornada</span><h2 style="margin-top:15px">${count===cases.length?'Laboratório concluído!':`${count} de ${cases.length} desafios concluídos`}</h2><div class="progress-bar"><div style="width:${count/cases.length*100}%"></div></div>${cases.map((c,i)=>`<div class="evidence-item"><strong>${Object.hasOwn(saved.best,i)?'✓':'○'} ${c.title}</strong>${Object.hasOwn(saved.best,i)?`${saved.best[i]} / 1.000 pontos`:'Ainda não concluído'}</div>`).join('')}<div class="modal-actions"><button class="primary" data-action="missions">Continuar praticando</button><button class="outline" data-action="export">Baixar relatório</button></div><p style="font-size:11px;margin-top:18px">O progresso é individual e fica neste navegador. Não há envio de dados para professores ou cadastro de alunos.</p></section>`}
function renderGuide(){app.innerHTML=title('Pense como um técnico.','Um método simples para investigar com segurança e aprender com cada resultado.')+`<article class="card guide"><span class="tag">Guia de bolso</span><h3>01 · Ouça e observe</h3><p>Identifique quando começou, o que mudou e em que situação a falha aparece. Um sintoma pode ter várias causas: ainda não é um diagnóstico.</p><h3>02 · Teste uma hipótese por vez</h3><p>Comece pelas conexões e pelas verificações simples. Compare com componentes comprovadamente funcionais e compatíveis. Registre o resultado de cada teste.</p><h3>03 · Proteja o equipamento e os dados</h3><p>Desligue, desconecte a alimentação e adote proteção contra descarga eletrostática antes de manipular componentes. Nunca abra uma fonte de alimentação. Faça backup antes de alterações que possam afetar dados.</p><h3>04 · Repare e valide</h3><p>Corrija a causa confirmada e repita o cenário que produzia a falha. Consulte o manual do fabricante: LEDs, códigos e limites variam entre modelos.</p><h3>Como funciona a pontuação?</h3><p>Cada caso começa com 1.000 pontos. Testes são gratuitos, cada diagnóstico errado desconta 150 pontos e a primeira dica desconta 100. Repetir uma pista ou rever a dica não custa pontos. O total soma apenas a melhor pontuação de cada caso.</p><h3>Sobre este laboratório</h3><p>Inspirado na dinâmica do Simulador de Defeitos fornecido como referência. Casos e ilustrações foram recriados para a web. Os resultados dos testes são simulados para fins de aprendizagem; em um equipamento real, os mesmos sintomas podem ter outras causas.</p><button class="primary" style="margin-top:24px" data-action="lab">Ir para a bancada →</button></article>`}
function start(i){current=i;saved.current=i;if(runs[i]?.solved)runs[i]=undefined;view='lab';modal.close();render();window.scrollTo(0,0)}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.view){view=b.dataset.view;render();return}if(b.dataset.start!==undefined)return start(Number(b.dataset.start));if(b.dataset.test!==undefined)return test(Number(b.dataset.test));const s=state(),c=cases[current];switch(b.dataset.action){case'close':modal.close();break;case'help':message('Observe. Teste. Resolva.','Leia o relato, clique no monitor ou no gabinete e faça os testes. Colete duas ou mais pistas, identifique a causa e aplique o reparo. Você começa com 1.000 pontos por caso: erros custam 150 e a primeira dica custa 100. Os testes não custam pontos.');break;case'power':if(!s.solved){if(!s.power&&current===0&&!s.solved){message('O computador não respondeu','A alimentação foi testada, mas o PC não ligou. A energia voltou a ser desconectada para continuar a investigação.');}else s.power=!s.power;render()}break;case'observe':message('Observação do monitor',s.solved?'O sistema iniciou e o sintoma foi resolvido.':s.power?`A tela mostra: ${c.screen}. Compare com o relato e execute os testes disponíveis.`:'O monitor não recebe sinal de vídeo. Isso, sozinho, não identifica a causa.');break;case'inspect':message('Observação do gabinete',s.power?'O gabinete está energizado. Use os testes para investigar e desconecte a energia antes de manipular componentes.':'A energia está desconectada. Agora você pode executar as inspeções internas da simulação.');break;case'hint':if(!s.hint){s.hint=true;s.penalty+=100}render();message('Uma pista para seu raciocínio',c.hint);break;case'diagnose':diagnose();break;case'repair':if((c.hardware&&s.power)||(!c.hardware&&!s.power)){document.querySelector('#repair-feedback').innerHTML=`<div class="feedback">${c.hardware?'Volte à bancada e desconecte a energia antes de aplicar o reparo.':'Volte à bancada e ligue o computador antes de aplicar o reparo.'}</div>`;return}s.solved=true;s.power=true;saved.best[current]=Math.max(saved.best[current]??0,Math.max(0,1000-s.penalty));render();result();break;case'next':modal.close();if(Object.keys(saved.best).length===cases.length){view='progress';render()}else start(cases.findIndex((_,i)=>!Object.hasOwn(saved.best,i)));break;case'missions':case'lab':view=b.dataset.action;modal.close();render();break;case'export':const rows=['Bancada PC — Relatório individual',...cases.map((c,i)=>`${c.title}: ${Object.hasOwn(saved.best,i)?saved.best[i]+' / 1000 pontos':'não concluído'}`),`Total: ${Object.values(saved.best).reduce((a,b)=>a+b,0)} / ${cases.length*1000} pontos`];const url=URL.createObjectURL(new Blob([rows.join('\r\n')],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='meu-progresso-bancada-pc.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break}});
document.addEventListener('submit',e=>{if(e.target.id!=='diagnostic-form')return;e.preventDefault();const val=Number(new FormData(e.target).get('answer')),s=state(),c=cases[current];if(val===c.answer){s.diagnosed=true;render();repair()}else{if(!s.wrong.includes(val)){s.wrong.push(val);s.penalty+=150}render();diagnose();document.querySelector('#answer-feedback').innerHTML='<div class="feedback">Essa hipótese não explica o conjunto das evidências. −150 pontos. Releia as pistas e teste outra hipótese.</div>'}});
document.querySelector('.close').onclick=()=>modal.close();modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});render();
